export interface LocationConfig {
  slug: string;
  cityName: string;
  title: string;
  description: string;
  canonical: string;

  heroImage: string;
  heroImageAlt: string;
  heroHeading: string;
  heroLead: string;

  introHeading: string;
  introParagraphs: string[];

  splitHeading: string;
  splitImage: string;
  splitImageAlt: string;
  splitParagraphs: string[];

  faqs: Faq[];
  schema: object[];
}

const BASE = 'https://www.allsafeit.com';
const TEAM_IMG = '/images/AllsafeIT-team.avif';

function schema(slug: string, city: string, serviceType = 'Managed IT Services'): object[] {
  return [
    {
      '@context': 'https://schema.org',
      '@type': 'Service',
      name: `${serviceType} ${city}`,
      url: `${BASE}/locations/${slug}`,
      serviceType,
      areaServed: { '@type': 'City', name: city },
      provider: { '@type': 'Organization', '@id': `${BASE}#organization` },
    },
    {
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'Home', item: BASE },
        { '@type': 'ListItem', position: 2, name: `IT Services ${city}`, item: `${BASE}/locations/${slug}` },
      ],
    },
  ];
}

